/* Builds dist/ for copy-paste deployment (no clasp): Code.gs (all server files), Index.html, appsscript.json. Usage: npm run bundle */
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..');
const order = ['Config.js', 'Util.js', 'SeedData.js', 'Pricing.js', 'DocData.js', 'DealLogic.js', 'AiLogic.js', 'GenLogic.js', 'AdminLogic.js', 'AcceptLogic.js', 'MasterData.js', 'Auth.js', 'Numbering.js', 'Deals.js', 'DocEngine.js', 'Ai.js', 'Generate.js', 'Accept.js', 'AcceptPage.js', 'Approvals.js', 'Admin.js', 'Ops.js', 'SetupMasterSheet.js', 'EngineSelfTest.js', 'EnvSetup.js', 'Code.js'];
const all = fs.readdirSync(path.join(root, 'src/server')).filter((f) => f.endsWith('.js'));
const missing = all.filter((f) => !order.includes(f));
if (missing.length) throw new Error('Add to bundle order: ' + missing.join(', '));
let out = '/**\n * OptCulture Sales Docs — bundled server code. GENERATED by `npm run bundle` from src/server/. Do not edit here.\n */\n';
order.forEach((f) => { out += `\n// ===================== ${f} =====================\n` + fs.readFileSync(path.join(root, 'src/server', f), 'utf8'); });
fs.writeFileSync(path.join(root, 'dist/Code.gs'), out);
fs.writeFileSync(path.join(root, 'dist/Index.html'), fs.readFileSync(path.join(root, 'src/ui/Index.html'), 'utf8'));
fs.writeFileSync(path.join(root, 'dist/appsscript.json'), fs.readFileSync(path.join(root, 'src/appsscript.json'), 'utf8'));
console.log('dist/ built: Code.gs (' + out.length + ' chars), Index.html, appsscript.json');

// Client acceptance page for Netlify (salestools.optculturecx.com/accept/<token>) – same page, fetch-based, no Google login involved.
const vm = require('vm');
const pageCtx = vm.createContext({});
vm.runInContext(fs.readFileSync(path.join(root, 'src/server/AcceptPage.js'), 'utf8'), pageCtx);
const execUrl = JSON.parse(fs.readFileSync(path.join(root, 'tools/public.json'), 'utf8')).publicExecUrl;
fs.mkdirSync(path.join(root, 'netlify/accept'), { recursive: true });
fs.writeFileSync(path.join(root, 'netlify/accept/index.html'), pageCtx.acceptPageHtml('netlify', { execUrl: execUrl }));
console.log('netlify/accept/index.html built (calls ' + execUrl.slice(0, 50) + '…)');
